"""Regresiones aisladas del control de monto basado en Usuario_Roles SQL.

No abren SQL, no usan credenciales y no alteran Produccion.
"""
import ast
import asyncio
from enum import Enum
from pathlib import Path
from types import SimpleNamespace

import pytest


_ROOT = Path(__file__).resolve().parents[1] / "modules" / "fase2_operativo" / "services"
_LEVELS = {
    "SUPERVISOR": 50,
    "GERENTE_OPS": 60,
    "DIRECCION": 80,
    "ADMIN": 90,
    "SUPERADMIN": 100,
}


class PermisoInsuficienteError(Exception):
    pass


class RolAutorizacion(str, Enum):
    SUPERVISOR = "SUPERVISOR"
    GERENTE_OPS = "GERENTE_OPS"
    DIRECCION = "DIRECCION"


class AccionResponsabilidad(str, Enum):
    EXONERAR = "EXONERAR"


class EstatusCargo(str, Enum):
    APLICADO = "APLICADO"
    REVERTIDO = "REVERTIDO"


class AccionCargo(str, Enum):
    REVERTIR = "REVERTIR"


def _method(filename, class_name, method_name, levels=None):
    tree = ast.parse((_ROOT / filename).read_text(encoding="utf-8"))
    cls = next(n for n in tree.body if isinstance(n, ast.ClassDef) and n.name == class_name)
    fn = next(
        n for n in cls.body
        if isinstance(n, ast.AsyncFunctionDef) and n.name == method_name
    )
    fn.decorator_list = []
    ns = {
        "get_role_level": lambda u: (levels if levels is not None else _LEVELS).get(u.get("role"), 0),
        "PermisoInsuficienteError": PermisoInsuficienteError,
        "RolAutorizacion": RolAutorizacion,
        "AccionResponsabilidad": AccionResponsabilidad,
        "EstatusCargo": EstatusCargo,
        "AccionCargo": AccionCargo,
        "CargoAccionResponse": lambda **kwargs: kwargs,
        "Optional": __import__("typing").Optional,
        "datetime": __import__("datetime").datetime,
        "timezone": __import__("datetime").timezone,
        "logger": SimpleNamespace(warning=lambda *args, **kwargs: None),
    }
    exec(compile(ast.fix_missing_locations(ast.Module(body=[fn], type_ignores=[])),
                 filename, "exec"), ns)
    return ns[method_name]


class _Config:
    async def get_valor_float(self, name, fallback):
        return 500 if name.endswith("SUPERVISOR") else 2000


@pytest.mark.parametrize(
    "role,monto,allowed",
    [
        ("SUPERVISOR", 500, True),
        ("SUPERVISOR", 501, False),
        ("GERENTE_OPS", 2000, True),
        ("GERENTE_OPS", 2001, False),
        ("DIRECCION", 2001, True),
        ("SUPERADMIN", 2500, True),
        ("ADMIN", 2500, True),
        ("DESCONOCIDO", 100, False),
    ],
)
def test_cargos_umbral_con_jerarquia_sql(role, monto, allowed):
    fn = _method("cargos_service.py", "CargosService", "_validar_permiso_por_monto")
    host = SimpleNamespace(UMBRAL_SUPERVISOR=500, UMBRAL_GERENTE=2000)
    if allowed:
        asyncio.run(fn(host, monto, role, "AUTORIZAR"))
    else:
        with pytest.raises(PermisoInsuficienteError):
            asyncio.run(fn(host, monto, role, "AUTORIZAR"))


@pytest.mark.parametrize(
    "role,monto,allowed",
    [
        ("SUPERVISOR", 500, True),
        ("SUPERVISOR", 501, False),
        ("GERENTE_OPS", 2000, True),
        ("GERENTE_OPS", 2001, False),
        ("DIRECCION", 2001, True),
        ("SUPERADMIN", 2500, True),
        ("DESCONOCIDO", 100, False),
    ],
)
def test_responsabilidad_umbral_con_jerarquia_sql(role, monto, allowed):
    fn = _method("responsabilidad_service.py", "ResponsabilidadService", "_validar_permiso_por_monto")
    host = SimpleNamespace(config_repo=_Config())
    if allowed:
        asyncio.run(fn(host, monto, role, "APROBAR"))
    else:
        with pytest.raises(PermisoInsuficienteError):
            asyncio.run(fn(host, monto, role, "APROBAR"))


def test_exonerar_exige_gerente_sql():
    fn = _method("responsabilidad_service.py", "ResponsabilidadService", "_validar_permiso_por_monto")
    host = SimpleNamespace(config_repo=_Config())
    with pytest.raises(PermisoInsuficienteError):
        asyncio.run(fn(host, 100, "SUPERVISOR", "EXONERAR"))
    asyncio.run(fn(host, 100, "SUPERADMIN", "EXONERAR"))


@pytest.mark.parametrize("filename,cls,host", [
    ("cargos_service.py", "CargosService", SimpleNamespace(UMBRAL_SUPERVISOR=500, UMBRAL_GERENTE=2000)),
    ("responsabilidad_service.py", "ResponsabilidadService", SimpleNamespace(config_repo=_Config())),
])
def test_sin_jerarquia_sql_no_hay_autorizacion(filename, cls, host):
    fn = _method(filename, cls, "_validar_permiso_por_monto", levels={})
    with pytest.raises(PermisoInsuficienteError):
        asyncio.run(fn(host, 50, "SUPERADMIN", "APROBAR"))


class _CargoRepo:
    def __init__(self):
        self.writes = 0

    async def actualizar_cargo(self, *args, **kwargs):
        self.writes += 1


class _CargoLog:
    async def registrar_log(self, **kwargs):
        return "log-ok"


class _CargoHost:
    def __init__(self):
        self.cargos_repo = _CargoRepo()
        self.log_repo = _CargoLog()

    async def _obtener_cargo(self, cargo_id):
        return {"estatus_cargo": "APLICADO", "monto_aplicado": 1000}

    async def _validar_transicion(self, *args):
        return None


@pytest.mark.parametrize("role,allowed", [
    ("SUPERVISOR", False),
    ("GERENTE_OPS", True),
    ("SUPERADMIN", True),
    ("DESCONOCIDO", False),
])
def test_revertir_cargo_verifica_jerarquia_sql(role, allowed):
    fn = _method("cargos_service.py", "CargosService", "revertir_cargo")
    host = _CargoHost()
    args = (host, "cargo-1", "actor-1", role, "Motivo de reversa suficientemente largo")
    if allowed:
        response = asyncio.run(fn(*args))
        assert response["success"] is True
        assert host.cargos_repo.writes == 1
    else:
        with pytest.raises(PermisoInsuficienteError):
            asyncio.run(fn(*args))
        assert host.cargos_repo.writes == 0
